## Log Line Constructor

Here's a clean JavaScript function that constructs a formatted log line:

```javascript
/**
 * Constructs a formatted log line from the given parameters.
 *
 * @param {string} level - The log level (e.g., 'INFO', 'WARN', 'ERROR', 'DEBUG')
 * @param {string} message - The log message
 * @param {Date|string|number} timestamp - The timestamp (Date object, ISO string, or Unix ms)
 * @returns {string} A formatted log line
 */
function constructLogLine(level, message, timestamp = new Date()) {
  const VALID_LEVELS = ['DEBUG', 'INFO', 'WARN', 'ERROR', 'FATAL'];

  // Validate and normalize level
  const normalizedLevel = String(level).toUpperCase().trim();
  if (!VALID_LEVELS.includes(normalizedLevel)) {
    throw new Error(`Invalid log level: "${level}". Must be one of: ${VALID_LEVELS.join(', ')}`);
  }

  // Validate message
  if (!message || typeof message !== 'string') {
    throw new Error('Message must be a non-empty string');
  }

  // Parse and validate timestamp
  const date = timestamp instanceof Date ? timestamp : new Date(timestamp);
  if (isNaN(date.getTime())) {
    throw new Error(`Invalid timestamp: "${timestamp}"`);
  }

  // Format: [YYYY-MM-DD HH:MM:SS.mmm] [LEVEL] message
  const formattedTimestamp = formatTimestamp(date);
  const paddedLevel = normalizedLevel.padEnd(5);

  return `[${formattedTimestamp}] [${paddedLevel}] ${message.trim()}`;
}

/**
 * Formats a Date object into a readable timestamp string.
 *
 * @param {Date} date
 * @returns {string} Formatted timestamp (YYYY-MM-DD HH:MM:SS.mmm)
 */
function formatTimestamp(date) {
  const pad = (n, digits = 2) => String(n).padStart(digits, '0');

  const year   = date.getFullYear();
  const month  = pad(date.getMonth() + 1);
  const day    = pad(date.getDate());
  const hours  = pad(date.getHours());
  const mins   = pad(date.getMinutes());
  const secs   = pad(date.getSeconds());
  const ms     = pad(date.getMilliseconds(), 3);

  return `${year}-${month}-${day} ${hours}:${mins}:${secs}.${ms}`;
}
```

