  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3,
  FATAL: 4,
};

function constructLogLine(level, message, timestamp, options = {}) {
  const { minLevel = "DEBUG", includeLevel = true } = options;

  if (!level || typeof level !== "string") {
    throw new TypeError("Level must be a non-empty string");
  }

  if (!message || typeof message !== "string") {
    throw new TypeError("Message must be a non-empty string");
  }

  const normalizedLevel = level.toUpperCase();

  if (!(normalizedLevel in LOG_LEVELS)) {
    throw new RangeError(
      `Invalid log level: "${level}". Must be one of: ${Object.keys(LOG_LEVELS).join(", ")}`
    );
  }

  // Filter out messages below the minimum log level
  if (LOG_LEVELS[normalizedLevel] < LOG_LEVELS[minLevel.toUpperCase()]) {
    return null;
  }

  const date =
    timestamp instanceof Date ? timestamp : new Date(timestamp ?? Date.now());

  if (isNaN(date.getTime())) {
    throw new RangeError(`Invalid timestamp: ${timestamp}`);
  }

  const formattedTimestamp = date.toISOString();
  const formattedLevel = normalizedLevel.padEnd(5);

  const parts = [`[${formattedTimestamp}]`];

  if (includeLevel) {
    parts.push(`[${formattedLevel}]`);
  }

  parts.push(message);

  return parts.join(" ");
}

