```javascript
const LOG_LEVELS = {
  DEBUG: 0,
  INFO: 1,
  WARN: 2,
  ERROR: 3,
  FATAL: 4,
};

/**
 * Constructs a log line with support for multiple output formats.
 *
 * @param {string} level - The log level
 * @param {string} message - The log message
 * @param {Date|string|number} timestamp - The timestamp
 * @param {Object} options - Optional configuration
 * @param {string} options.format - Output format: 'text' (default) or 'json'
 * @param {Object} options.meta - Additional metadata to include
 * @returns {string} A formatted log line
 */
function buildLogLine(level, message, timestamp = new Date(), options = {}) {
  const { format = "text", meta = {} } = options;

  if (!level || typeof level !== "string") {
    throw new TypeError("Log level must be a non-empty string");
  }

  if (!message || typeof message !== "string") {
    throw new TypeError("Log message must be a non-empty string");
  }

  const normalizedLevel = level.toUpperCase();

  if (!LOG_LEVELS.hasOwnProperty(normalizedLevel)) {
    throw new RangeError(
      `Invalid log level: "${level}". Must be one of: ${Object.keys(LOG_LEVELS).join(", ")}`
    );
  }

  const date = timestamp instanceof Date ? timestamp : new Date(timestamp);

  if (isNaN(date.getTime())) {
    throw new RangeError(`Invalid timestamp: ${timestamp}`);
  }

  const logEntry = {
    timestamp: date.toISOString(),
    level: normalizedLevel,
    message,
    ...meta,
  };

  if (format === "json") {
    return JSON.stringify(logEntry);
  }

  const metaString =
    Object.keys(meta).length > 0
      ? " " + Object.entries(meta).map(([k, v]) => `${k}=${v}`).join(" ")
      : "";

  return `[${logEntry.timestamp}] [${normalizedLevel.padEnd(5)}] ${message}${metaString}`;
}
