 * Generates a greeting based on a name and a specified time of day string.
 *
 * @param {string} name The name of the person to greet.
 * @param {string} timeOfDay The time of day ('morning', 'afternoon', or 'evening').
 * @returns {string} A personalized greeting string.
 */
function getGreetingByString(name, timeOfDay) {
  // Use toLowerCase() to make the input case-insensitive
  const normalizedTime = timeOfDay.toLowerCase();
  let greeting;

  switch (normalizedTime) {
    case 'morning':
      greeting = 'Good morning';
      break;
    case 'afternoon':
      greeting = 'Good afternoon';
      break;
    case 'evening':
      greeting = 'Good evening';
      break;
    default:
      greeting = 'Hello'; // A fallback for unknown inputs
      break;
  }

  return `${greeting}, ${name}!`;
}

// --- Examples ---
