  console.error(error.message); // Output: "Invalid token provided. Token must be a non-empty string."
}
```

### How to Use It with `fetch`

Here’s how you would use this function to make an authenticated API request using the `fetch` API.

```javascript
// Assume createBearerAuthHeader function is defined as above

async function fetchUserProfile(userId, token) {
  const apiUrl = `https://api.example.com/users/${userId}`;

  try {
    const response = await fetch(apiUrl, {
      method: 'GET',
      headers: {
        // Here we use the function to build the header value
        'Authorization': createBearerAuthHeader(token),
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      // Handle HTTP errors like 401 Unauthorized or 404 Not Found
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();
    console.log('User Profile:', data);
    return data;

  } catch (error) {
    console.error('Failed to fetch user profile:', error);
  }
}

// --- Example Call ---
const userToken = 'a_very_secret_and_long_api_token';
fetchUserProfile('user123', userToken);
```

### Key Points to Remember

1.  **The Space is Crucial:** The format is always `Bearer` followed by a single space, then the token (`Bearer <token>`). The function handles this for you.
2.  **Security:** Never hardcode tokens directly in your client-side JavaScript code that is visible to users. Tokens should be retrieved from a secure location, such as:
    *   An HttpOnly cookie.
    *   A secure in-memory variable after a login process.
    *   For server-side Node.js, from environment variables or a secrets management service.
3.  **Arrow Function Syntax:** You can also write this function concisely as an arrow function:

    ```javascript
    const createBearerAuthHeader = (token) => `Bearer ${token}`;
    ```
